begin;
create function pg_temp.check_scenario(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL: %',label;end if;raise notice 'PASS: %',label;end$$;
create function pg_temp.expect_scenario(statement text,code text,label text) returns void language plpgsql as $$begin begin execute statement;exception when others then if sqlstate=code then raise notice 'PASS: %',label;return;end if;raise;end;raise exception 'FAIL: %',label;end$$;
insert into auth.users(id) values ('60020000-0000-4000-8000-000000000001'),('60020000-0000-4000-8000-000000000002');
insert into public.properties values ('hu60-s-p','60020000-0000-4000-8000-000000000001','{}','2026-10-11T00:00:00Z'),('hu60-s-other','60020000-0000-4000-8000-000000000001','{}','2026-10-11T00:00:00Z'),('hu60-s-foreign','60020000-0000-4000-8000-000000000002','{}','2026-10-11T00:00:00Z');
insert into public.analysis_scenarios(id,property_id,user_id,label,payload,created_at) values ('hu60-s-source','hu60-s-p','60020000-0000-4000-8000-000000000001','Original','{"engine":"historical","result":{"profit":123.45}}',now()),('hu60-s-wrong','hu60-s-other','60020000-0000-4000-8000-000000000001','Other','{}',now()),('hu60-s-hidden','hu60-s-foreign','60020000-0000-4000-8000-000000000002','Hidden','{}',now());
insert into public.analysis_baselines values ('hu60-s-p','60020000-0000-4000-8000-000000000001','hu60-s-source',now());
set local role authenticated;
select set_config('request.jwt.claim.sub','60020000-0000-4000-8000-000000000001',true);
select public.duplicate_owned_scenario('hu60-s-p','hu60-s-source','2026-10-11T00:00:00Z',null,'Copy','60020000-0000-4000-8000-000000000010');
select pg_temp.check_scenario((select count(*)=1 and bool_and(payload='{"engine":"historical","result":{"profit":123.45}}'::jsonb) from public.analysis_scenarios where source_id='hu60-s-source'),'copy preserves historical engine and results');
select pg_temp.check_scenario((select scenario_id='hu60-s-source' from public.analysis_baselines where property_id='hu60-s-p'),'approved baseline untouched');
select pg_temp.check_scenario((select count(*)=1 and bool_and(payload->>'actor'='60020000-0000-4000-8000-000000000001') from public.audit_events where property_id='hu60-s-p'),'audit created with verified actor');
select pg_temp.check_scenario((public.duplicate_owned_scenario('hu60-s-p','hu60-s-source','2026-10-10T20:00:00-04:00',null,'Copy','60020000-0000-4000-8000-000000000010')->>'replayed')::boolean and (select count(*)=2 from public.analysis_scenarios where property_id='hu60-s-p'),'retry without duplicate');
select pg_temp.expect_scenario($q$select public.duplicate_owned_scenario('hu60-s-p','hu60-s-source','2026-10-11T00:00:00Z',null,'Changed','60020000-0000-4000-8000-000000000010')$q$,'40001','same request changed body denied');
select pg_temp.expect_scenario($q$select public.duplicate_owned_scenario('hu60-s-p','hu60-s-source','2026-10-10T00:00:00Z',null,'Stale','60020000-0000-4000-8000-000000000011')$q$,'40001','stale property denied');
select pg_temp.expect_scenario($q$select public.duplicate_owned_scenario('hu60-s-p','hu60-s-source','2026-10-11T00:00:00Z','2026-10-11T00:00:00Z','Stale','60020000-0000-4000-8000-000000000012')$q$,'40001','book version checked');
select pg_temp.expect_scenario($q$select public.duplicate_owned_scenario('hu60-s-foreign','hu60-s-hidden','2026-10-11T00:00:00Z',null,'Hidden','60020000-0000-4000-8000-000000000013')$q$,'42501','other owner denied');
select pg_temp.expect_scenario($q$select public.duplicate_owned_scenario('hu60-s-p','hu60-s-wrong','2026-10-11T00:00:00Z',null,'Wrong property','60020000-0000-4000-8000-000000000014')$q$,'42501','source must belong to same property');
reset role;
create function pg_temp.fail_scenario_audit() returns trigger language plpgsql as $$begin if new.property_id='hu60-s-p' then raise exception using errcode='P0001',message='Synthetic audit failure';end if;return new;end$$;
create trigger hu60_test_scenario_failure before insert on public.audit_events for each row execute function pg_temp.fail_scenario_audit();
set local role authenticated;
select pg_temp.expect_scenario($q$select public.duplicate_owned_scenario('hu60-s-p','hu60-s-source','2026-10-11T00:00:00Z',null,'Rollback','60020000-0000-4000-8000-000000000015')$q$,'P0001','audit failure propagates');
select pg_temp.check_scenario((select count(*)=2 from public.analysis_scenarios where property_id='hu60-s-p') and (select count(*)=1 from public.audit_events where property_id='hu60-s-p'),'copy rolled back when audit fails');
reset role;
drop trigger hu60_test_scenario_failure on public.audit_events;
insert into public.analysis_scenarios(id,property_id,user_id,label,payload,created_at) select 'hu60-s-fill-'||n,'hu60-s-p','60020000-0000-4000-8000-000000000001','Fill','{}',now() from generate_series(1,48)n;
set local role authenticated;
select pg_temp.expect_scenario($q$select public.duplicate_owned_scenario('hu60-s-p','hu60-s-source','2026-10-11T00:00:00Z',null,'Limit','60020000-0000-4000-8000-000000000016')$q$,'40001','50 scenario limit enforced');
reset role;
select pg_temp.check_scenario(not has_function_privilege('anon','public.duplicate_owned_scenario(text,text,timestamptz,timestamptz,text,uuid)','execute') and not has_table_privilege('authenticated','public.analysis_scenarios','insert'),'anonymous RPC and direct writes denied');
rollback;
